/* From Uiverse.io by Samalander0 - Tags: card, hover, rounded, hover effect */
.__UIV_SCOPE__ .card {
  width: 320px;
  background: #fff480;
  color: black;
  position: relative;
  border-radius: 2.5em;
  padding: 2em;
  transition: transform 0.4s ease;
}

.__UIV_SCOPE__ .card .card-content {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 5em;
  height: 100%;
  transition: transform 0.4s ease;
}

.__UIV_SCOPE__ .card .card-top, .__UIV_SCOPE__ .card .card-bottom {
  display: flex;
  justify-content: space-between;
}

.__UIV_SCOPE__ .card .card-top p, .__UIV_SCOPE__ .card .card-top .card-title, .__UIV_SCOPE__ .card .card-bottom p, .__UIV_SCOPE__ .card .card-bottom .card-title {
  margin: 0;
}

.__UIV_SCOPE__ .card .card-title {
  font-weight: bold;
}

.__UIV_SCOPE__ .card .card-top p, .__UIV_SCOPE__ .card .card-bottom p {
  font-weight: 600;
}

.__UIV_SCOPE__ .card .card-bottom {
  align-items: flex-end;
}

.__UIV_SCOPE__ .card .card-image {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  display: grid;
  place-items: center;
  pointer-events: none;
}

.__UIV_SCOPE__ .card .card-image svg {
  width: 4em;
  height: 4em;
  transition: transform 0.4s ease;
}

.__UIV_SCOPE__ .card:hover {
  cursor: pointer;
  transform: scale(0.97);
}

.__UIV_SCOPE__ .card:hover .card-content {
  transform: scale(0.96);
}

.__UIV_SCOPE__ .card:hover .card-image svg {
  transform: scale(1.05);
}

.__UIV_SCOPE__ .card:active {
  transform: scale(0.9);
}
